LEGAL_CUT_ROLES = {"user", "assistant", "assistant_progress", "assistant_tool_call"}


def _is_legal_cut(messages, cut):
    """Return True when messages[cut:] may remain while messages[:cut] are summarized.

    A legal cut must start on a message role that can open the retained span
    (or at the end of the message list, which means everything is summarized).
    It must also preserve the call/result invariant: no removed
    ``assistant_tool_call`` toolUseId may appear among retained ``tool_result``
    messages.
    """

    if cut < 0 or cut > len(messages):
        return False

    # A tool_result is never a legal first retained message, even when its
    # pairing is malformed.
    if cut < len(messages):
        if messages[cut].get("role") not in LEGAL_CUT_ROLES:
            return False

    removed = messages[:cut]
    retained = messages[cut:]

    removed_call_ids = {
        message.get("toolUseId")
        for message in removed
        if message.get("role") == "assistant_tool_call"
        and message.get("toolUseId") is not None
    }

    for message in retained:
        if (
            message.get("role") == "tool_result"
            and message.get("toolUseId") in removed_call_ids
        ):
            return False

    return True


def choose(messages, proposed):
    """Return the first legal cut index at or after ``proposed``.

    ``proposed`` is the desired boundary: messages before it are summarized and
    messages from it onward remain. We never move the boundary toward older
    messages. If no legal boundary exists at or after ``proposed``, return
    ``len(messages)``, meaning the complete span should be summarized.
    """

    if not isinstance(proposed, int):
        raise TypeError("proposed must be an integer")

    start = max(proposed, 0)
    for cut in range(start, len(messages) + 1):
        if _is_legal_cut(messages, cut):
            return cut
    return len(messages)

LEGAL_START_ROLES = {
    "user",
    "assistant",
    "assistant_progress",
    "assistant_tool_call",
}

TOOL_CALL_ROLE = "assistant_tool_call"
TOOL_RESULT_ROLE = "tool_result"


def _get_role(message):
    if isinstance(message, dict):
        return message.get("role")
    return getattr(message, "role", None)


def _get_tool_use_id(message):
    if isinstance(message, dict):
        return message.get("toolUseId")
    return getattr(message, "toolUseId", None)


def choose(messages, proposed):
    """Return a legal conversation-reducer cut boundary.

    The boundary is the first message index at or after ``proposed`` whose
    role may start the retained suffix and that does not split an internal
    tool call from its result.  A cut is illegal when a removed tool call's
    ID still appears on a retained tool result.
    """
    n = len(messages)
    start = max(int(proposed), 0)

    for index in range(start, n):
        if _get_role(messages[index]) not in LEGAL_START_ROLES:
            continue

        removed_tool_use_ids = {
            _get_tool_use_id(message)
            for message in messages[:index]
            if _get_role(message) == TOOL_CALL_ROLE
            and _get_tool_use_id(message) is not None
        }

        retained_has_orphaned_result = any(
            _get_role(message) == TOOL_RESULT_ROLE
            and _get_tool_use_id(message) in removed_tool_use_ids
            for message in messages[index:]
        )

        if not retained_has_orphaned_result:
            return index

    return n

