    "assistant",
    "assistant_progress",
    "assistant_tool_call",
}


def _get(message, key, default=None):
    if isinstance(message, dict):
        return message.get(key, default)
    return getattr(message, key, default)


def _is_legal_cut(messages, cut):
    """Return True when messages[:cut] can be summarized safely."""
    if cut < 0 or cut > len(messages):
        return False

    # Summarizing the complete span is always allowed; there are no
    # retained tool results that could reference a removed tool call.
    if cut == len(messages):
        return True

    # A tool_result may not start the retained span, even if its pairing
    # is malformed.
    if _get(messages[cut], "role") not in _LEGAL_CUT_ROLES:
        return False

    removed_tool_use_ids = set()
    for message in messages[:cut]:
        if _get(message, "role") == "assistant_tool_call":
            tool_use_id = _get(message, "toolUseId")
            if tool_use_id is not None:
                removed_tool_use_ids.add(tool_use_id)

    for message in messages[cut:]:
        if _get(message, "role") == "tool_result":
            tool_use_id = _get(message, "toolUseId")
            if tool_use_id is not None and tool_use_id in removed_tool_use_ids:
                return False

    return True


