def choose(messages, proposed):
    """Return the first legal reduction boundary at or after *proposed*.

    A boundary is an index into ``messages``: messages before the boundary are
    summarized away, while messages from the boundary onward are retained.

    Legal boundary roles are ``user``, ``assistant``, ``assistant_progress``,
    and ``assistant_tool_call``.  A boundary is additionally illegal if any
    removed ``assistant_tool_call`` still has its ``tool_result`` retained.
    """
    legal_roles = {"user", "assistant", "assistant_progress", "assistant_tool_call"}
    start = max(0, proposed)

    for index in range(start, len(messages)):
        if messages[index].get("role") not in legal_roles:
            continue

        removed_call_ids = {
            message.get("toolUseId")
            for message in messages[:index]
            if message.get("role") == "assistant_tool_call"
        }
        retained_result_ids = {
            message.get("toolUseId")
            for message in messages[index:]
            if message.get("role") == "tool_result"
        }

        if removed_call_ids.isdisjoint(retained_result_ids):
            return index

    return len(messages)

def choose(messages, proposed):
    """Choose the earliest legal conversation cut boundary.

    Messages before the returned index are summarized; messages from the
    returned index onward remain.  A legal boundary must start on a message
    whose role can begin a retained span, and it must not split an internal
    tool call from its matching tool result: if a removed
    ``assistant_tool_call``'s ``toolUseId`` is still present on a retained
    ``tool_result``, the boundary is illegal.
    """

    legal_roles = {
        "user",
        "assistant",
        "assistant_progress",
        "assistant_tool_call",
    }

    # Never move toward older messages.  Treat out-of-range proposals as the
    # end of the conversation so the complete span is summarized.
    if proposed < 0:
        proposed = 0
    if proposed > len(messages):
        proposed = len(messages)

    for index in range(proposed, len(messages)):
        message = messages[index]
        if not isinstance(message, dict):
            continue

        role = message.get("role")
        if role not in legal_roles:
            continue

        removed_ids = set()
        for removed in messages[:index]:
            if not isinstance(removed, dict):
                continue
            if removed.get("role") == "assistant_tool_call":
                tool_use_id = removed.get("toolUseId")
                if tool_use_id is not None:
                    removed_ids.add(tool_use_id)

        retained_has_removed_result = False
        for retained in messages[index:]:
            if not isinstance(retained, dict):
                continue
            if retained.get("role") != "tool_result":
                continue
            tool_use_id = retained.get("toolUseId")
            if tool_use_id is not None and tool_use_id in removed_ids:
                retained_has_removed_result = True
                break

        if not retained_has_removed_result:
            return index

    return len(messages)

